    if ((wheel_axes_body == NULL) || (desired_body_torque_nm == NULL) || 
        (wheel_torque_limit_nm == NULL) || (wheel_torque_nm == NULL) || 
        (achieved_body_torque_nm == NULL) || (saturation_mask == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Check finiteness of all input vectors and limits
    if (!adcs_is_finite_vec3(&wheel_axes_body[0]) || !adcs_is_finite_vec3(&wheel_axes_body[1]) || 
        !adcs_is_finite_vec3(&wheel_axes_body[2]) || 
        !adcs_is_finite_vec3(desired_body_torque_nm)) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(wheel_torque_limit_nm[0]) || !isfinite(wheel_torque_limit_nm[1]) || 
        !isfinite(wheel_torque_limit_nm[2])) {
        return ADCS_E_RANGE;
    }

    // Initialize outputs to zero for failure safety
    *achieved_body_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    *saturation_mask = 0U;

    // 3. Validate the triad: unit norms and mutual orthogonality within 1e-10 tolerance
    const double tol = 1e-10;
    double n0 = adcs_vec3_norm(&wheel_axes_body[0]);
    double n1 = adcs_vec3_norm(&wheel_axes_body[1]);
    double n2 = adcs_vec3_norm(&wheel_axes_body[2]);

    if (fabs(n0 - 1.0) > tol || fabs(n1 - 1.0) > tol || fabs(n2 - 1.0) > tol) {
        return ADCS_E_RANGE;
    }

    double d01 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[1]);
    double d02 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[2]);
    double d12 = adcs_vec3_dot(&wheel_axes_body[1], &wheel_axes_body[2]);

    if (fabs(d01) > tol || fabs(d02) > tol || fabs(d12) > tol) {
        return ADCS_E_RANGE;
    }

    // 4. Allocate, clamp, and reconstruct achieved torque
    double u_unconstrained[3];
    unint32 sat_mask = 0U;

    for (int i = 0; i < 3; ++i) {
        // Unconstrained motor command: u_i = - a_i . tau_desired
        u_unconstrained[i] = -adcs_vec3_dot(&wheel_axes_body[i], desired_body_torque_nm);

        double limit = wheel_torque_limit_nm[i];
        double u_clamped = u_unconstrained[i];
        int is_saturated = 0;

        // Clamp each u_i independently
        if (u_clamped > limit) {
            u_clamped = limit;
            is_saturated = 1;
        } else if (u_clamped < -limit) {
            u_clamped = -limit;
            is_saturated = 1;
        }

        wheel_torque_nm[i] = u_clamped;

        // Set saturation mask bit if clamped
        if (is_saturated) {
            sat_mask |= (1U << i);
        }
    }

    // Achieved spacecraft torque is -sum (clamped u_i) * a_i
    adcs_vec3_t tau_achieved = {0.0, 0.0, 0.0};
    for (int i = 0; i < 3; ++i) {
        adcs_vec3_t term = adcs_vec3_scale(&wheel_axes_body[i], wheel_torque_nm[i]);
        tau_achieved = adcs_vec3_sub(&tau_achieved, &term);
    }

    *achieved_body_torque_nm = tau_achieved;
    *saturation_mask = sat_mask;

    return ADCS_OK;
}

